window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-430864db3b85c854"]={"versions": [{"id": "FIG-430864db3b85c854", "releases": ["R1.3.0", "R1.5.1", "R17-03_R1.1.0", "R17-10_R1.2.0", "R18-03_R1.4.0", "R18-10_R4.4.0_R1.5.0", "R19-03", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Bitfeld- und Protokolldaten-Strukturdiagramm aus der AUTOSAR-Spezifikation für das Log- und Trace-Protokoll (AUTOSAR_PRS_LogAndTraceProtocol). Das Diagramm visualisiert das Bit-Layout des 1-Byte-Steuerfeldes „Message Info (MSIN)“ innerhalb des Dlt-Nachrichtenheaders.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Message-Info-Feld (MSIN) umfasst genau ein Byte (Byte 0) mit aufsteigender Bit-Nummerierung von Bit 0 bis Bit 7:</p>\n<ul class=\"fig-list\"><li><code>VERB</code> (Verbose-Flag): Bit-Offset 0 (1 Bit).\n</li><li><code>MSTP</code> (Message Type): Bit-Offsets 1 bis 3 (3 Bits).\n</li><li><code>MTIN</code> (Message Type Info): Bit-Offsets 4 bis 7 (4 Bits).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm zeigt eine statische Bit-Kodierung. Bei der Serialisierung und Deserialisierung von Dlt-Nachrichten wird das MSIN-Feld als Byte 0 im Header übertragen, wobei Bit 0 (<code>VERB</code>) über den Verbose-Modus entscheidet, die Bits 1 bis 3 (<code>MSTP</code>) den Nachrichtentyp codieren und die Bits 4 bis 7 (<code>MTIN</code>) den spezifischen Subtyp bzw. die Zusatzinformation zum Nachrichtentyp bereitstellen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives Datenlayout für Parser und Generatoren des Dlt-Protokolls. Bei der Implementierung ist auf die Bit-Offsets zu achten: Bit 0 definiert das Verbose-Bit (<code>VERB</code>), Bits 1–3 den Nachrichtentyp (<code>MSTP</code>) und Bits 4–7 die Nachrichtentyp-Information (<code>MTIN</code>). Die Bit-Reihenfolge ist in der Abbildung mit Bit 0 an der niedrigstwertigen Position links dargestellt.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-2317cfc07b1141ec", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Bitfeld- und Protokolldaten-Strukturdiagramm aus der AUTOSAR-Spezifikation für das Log- und Trace-Protokoll (AUTOSAR_PRS_LogAndTraceProtocol). Das Diagramm visualisiert das Bit-Layout des 1-Byte-Steuerfeldes „Message Info (MSIN)“ innerhalb des Dlt-Nachrichtenheaders.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Message-Info-Feld (MSIN) umfasst genau ein Byte (Byte 0) mit absteigender Bit-Nummerierung von Bit 7 bis Bit 0 (MSB nach LSB):</p>\n<ul class=\"fig-list\"><li><code>MTIN</code> (Message Type Info): Bit-Offsets 7 bis 4 (4 Bits, Bits 7, 6, 5, 4).\n</li><li><code>MSTP</code> (Message Type): Bit-Offsets 3 bis 1 (3 Bits, Bits 3, 2, 1).\n</li><li><code>VERB</code> (Verbose-Flag): Bit-Offset 0 (1 Bit).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm zeigt eine statische Bit-Kodierung. Bei der Serialisierung und Deserialisierung von Dlt-Nachrichten wird das MSIN-Feld als Byte 0 im Header übertragen, wobei Bit 0 (<code>VERB</code>) über den Verbose-Modus entscheidet, die Bits 1 bis 3 (<code>MSTP</code>) den Nachrichtentyp codieren und die Bits 4 bis 7 (<code>MTIN</code>) den spezifischen Subtyp bzw. die Zusatzinformation zum Nachrichtentyp bereitstellen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives Datenlayout für Dlt-Nachrichtenparser und -generatoren. Das MSIN-Byte wird mit MSB-Links-Konvention dargestellt: Bit 7 bis 4 für <code>MTIN</code>, Bits 3 bis 1 für <code>MSTP</code> und Bit 0 für das Flag <code>VERB</code>. Die physikalische Bit-Zuordnung entspricht der Big-Endian-/MSB-Erst-Darstellung von Kommunikationsprotokollen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-9f78ea4e204d45ec", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Bitfeld- und Protokolldaten-Strukturdiagramm aus der AUTOSAR-Spezifikation für das Log- und Trace-Protokoll (AUTOSAR_PRS_LogAndTraceProtocol). Das Diagramm visualisiert das Bit-Layout des 1-Byte-Steuerfeldes „Message Info (MSIN)“ innerhalb des Dlt-Nachrichtenheaders.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Message-Info-Feld (MSIN) umfasst genau ein Byte (Byte 0) mit absteigender Bit-Nummerierung von Bit 7 bis Bit 0 (MSB nach LSB):</p>\n<ul class=\"fig-list\"><li><code>MTIN</code> (Message Type Info): Bit-Offsets 7 bis 4 (4 Bits, Bits 7, 6, 5, 4).\n</li><li><code>MSTP</code> (Message Type): Bit-Offsets 3 bis 1 (3 Bits, Bits 3, 2, 1).\n</li><li><code>reserved</code>: Bit-Offset 0 (1 Bit).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm zeigt eine statische Bit-Kodierung. Bei der Übertragung und Dekodierung des Dlt-Headers enthält Byte 0 (MSIN) in den Bits 7 bis 4 die <code>MTIN</code>-Subtyp-Informationen und in den Bits 3 bis 1 den Hauptnachrichtentyp <code>MSTP</code>. Bit 0 ist reserviert und führt kein Verbose-Flag mehr.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives Protokolllayout. Bit 0 ist als <code>reserved</code> definiert und darf nicht mehr als <code>VERB</code>-Flag ausgewertet oder belegt werden. Parser müssen Bit 0 ignorieren bzw. Generatoren müssen den reservierten Wert vorschriftsmäßig setzen. Bits 7 bis 4 codieren <code>MTIN</code>, Bits 3 bis 1 codieren <code>MSTP</code>.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-a9844be1864f4dd1", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Bitfeld- und Protokolldaten-Strukturdiagramm aus der AUTOSAR-Spezifikation für das Log- und Trace-Protokoll (AUTOSAR_PRS_LogAndTraceProtocol). Das Diagramm visualisiert das Bit-Layout des 1-Byte-Steuerfeldes „Message Info (MSIN)“ innerhalb des Dlt-Nachrichtenheaders.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Message-Info-Feld (MSIN) umfasst genau ein Byte (Byte 0) mit absteigender Bit-Nummerierung von Bit 7 bis Bit 0 (MSB nach LSB):</p>\n<ul class=\"fig-list\"><li><code>MTIN</code> (Message Type Info): Bit-Offsets 7 bis 4 (4 Bits, Bits 7, 6, 5, 4).\n</li><li><code>MSTP</code> (Message Type): Bit-Offsets 3 bis 1 (3 Bits, Bits 3, 2, 1).\n</li><li><code>reserved</code>: Bit-Offset 0 (1 Bit).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm zeigt eine statische Bit-Kodierung. Bei der Übertragung und Dekodierung des Dlt-Headers enthält Byte 0 (MSIN) in den Bits 7 bis 4 die <code>MTIN</code>-Subtyp-Informationen und in den Bits 3 bis 1 den Hauptnachrichtentyp <code>MSTP</code>. Bit 0 ist reserviert und führt kein Verbose-Flag mehr.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives Protokolllayout. Bit 0 ist als <code>reserved</code> definiert und darf nicht mehr als <code>VERB</code>-Flag ausgewertet oder belegt werden. Parser müssen Bit 0 ignorieren bzw. Generatoren müssen den reservierten Wert vorschriftsmäßig setzen. Bits 7 bis 4 codieren <code>MTIN</code>, Bits 3 bis 1 codieren <code>MSTP</code>.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-430864db3b85c854", "to": "FIG-2317cfc07b1141ec", "fr": "R19-11", "tr": "R20-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Umkehrung der Bit-Reihenfolge in der tabellarischen Darstellung: Bits sind nun absteigend von links nach rechts (Bit 7 bis 0 statt 0 bis 7) angeordnet.\n</li><li>Vertauschung der visuellen Spaltenpositionen entsprechend der Bit-Reihenfolge: <code>MTIN</code> steht nun links (Bits 7 bis 4), gefolgt von <code>MSTP</code> (Bits 3 bis 1) und <code>VERB</code> ganz rechts (Bit 0). Die Bit-Zuordnung der Felder bleibt inhaltlich identisch.\n</li></ul>"}, {"from": "FIG-2317cfc07b1141ec", "to": "FIG-9f78ea4e204d45ec", "fr": "R20-11", "tr": "R21-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Feld <code>VERB</code> an Bit-Offset 0 ersetzt durch <code>reserved</code>.\n</li><li>Farbliche Hervorhebung der Titelzeile <code>Message Info (MSIN)</code> von Blau zu Orange geändert.\n</li></ul>"}, {"from": "FIG-9f78ea4e204d45ec", "to": "FIG-a9844be1864f4dd1", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
